基础 IVR 菜单<pre><code>context ivrmenu {
    s =&gt; {
        Answer();
        Background(main-menu); // 播放语音提示
        WaitExten(10);
    }

    1 =&gt; {
        Playback(option-1);
        Hangup();
    }

    2 =&gt; {
        Playback(option-2);
        Hangup();
    }

    i =&gt; { // 无效输入
        Playback(pbx-invalid);
        goto s;
    }

    t =&gt; { // 超时
        Playback(vm-goodbye);
        Hangup();
    }
}
</code></pre>

登录成功 / 登出成功语音提示<pre><code>; 播放提示语音 agent-loginok 或 agent-loggedoff；
; 根据 exten 首字母判断操作类型。
macro queue-success(exten) {
  if (${queue-announce-success} &gt; 0) {
    switch(${exten:0:1}) {
      case I:
        Playback(agent-loginok);
        Hangup();
        break;
      case O:
        Playback(agent-loggedoff);
        Hangup();
        break;
    }
  }
}
</code></pre> 增删成员宏：queue-addremove<pre><code>; exten:1 去掉首字母提取工号；
; 使用 Local 通道将坐席映射到实际分机；
; 支持 暂停（P） 和 恢复（U） 但本示例中暂未使用。
macro queue-addremove(queuename, penalty, exten) {
  switch(${exten:0:1}) {
    case I:
      AddQueueMember(${queuename},Local/${exten:1}@agents,${penalty});
      break;
    case O:
      RemoveQueueMember(${queuename},Local/${exten:1}@agents);
      break;
    case P:
      PauseQueueMember(${queuename},Local/${exten:1}@agents);
      break;
    case U:
      UnpauseQueueMember(${queuename},Local/${exten:1}@agents);
      break;
    default:
      Playback(invalid);
      break;
  }
}
</code></pre>

